style.css:
@-moz-document regexp("https?://.*") {
/* ========== PURE BLACK PALETTE ========== */
  :root {
    --bg-0: #000000;
    --bg-1: #0a0a0a;
    --bg-2: #111111;
    --bg-3: #1a1a1a;
    --bg-4: #222222;

    --text-1: #e8e8e8;
    --text-2: #b0b0b0;
    --text-3: #777777;
  }

  /* ========== BASE ========== */
  html {
    background: var(--bg-0) !important;
    color-scheme: dark only !important;
  }

  body {
    background: var(--bg-0) !important;
    color: var(--text-1) !important;
    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif !important;
  }

  /* ========== ANIME GIRL DECORATION ========== */
  body::after {
    content: "" !important;
    position: fixed !important;
    bottom: 0 !important;
    right: 0 !important;
    width: 380px !important;
    height: 520px !important;
    background-image: url("https://i.imgur.com/8QZQZQZ.png") !important; /* ← Replace this URL with your preferred anime girl image */
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: bottom right !important;
    opacity: 0.22 !important;
    pointer-events: none !important;
    z-index: 99999 !important;
    filter: grayscale(30%) brightness(0.85) !important;
  }

  /* ========== FORCE DARK BACKGROUNDS ========== */
  body,
  main,
  article,
  section,
  aside,
  header,
  footer,
  nav,
  div,
  [class*="container"],
  [class*="wrapper"],
  [class*="content"],
  [class*="panel"],
  [class*="card"],
  [class*="box"],
  [class*="modal"],
  [class*="dialog"],
  [class*="menu"],
  [class*="sidebar"],
  [class*="header"],
  [class*="footer"],
  [class*="nav"] {
    background-color: var(--bg-0) !important;
    background-image: none !important;
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
  }

  /* Slight elevation for important areas */
  header,
  nav,
  [class*="navbar"],
  [class*="topbar"],
  [class*="sidebar"] {
    background-color: var(--bg-1) !important;
  }

  /* Cards / panels */
  [class*="card"],
  [class*="panel"],
  [class*="modal"],
  [class*="popup"],
  [class*="dialog"] {
    background-color: var(--bg-2) !important;
  }

  /* ========== TEXT ========== */
  h1, h2, h3, h4, h5, h6,
  p, span, li, label, td, th, a {
    color: var(--text-1) !important;
    border: none !important;
    text-shadow: none !important;
  }

  a {
    color: var(--text-2) !important;
  }

  a:hover {
    color: #ffffff !important;
  }

  /* ========== BUTTONS ========== */
  button,
  [role="button"],
  input[type="submit"],
  input[type="button"],
  .btn,
  [class*="button"] {
    background: var(--bg-3) !important;
    color: var(--text-1) !important;
    border: none !important;
    border-radius: 6px !important;
    box-shadow: none !important;
  }

  button:hover,
  [role="button"]:hover,
  .btn:hover {
    background: var(--bg-4) !important;
    color: #ffffff !important;
  }

  /* ========== INPUTS ========== */
  input,
  textarea,
  select {
    background: var(--bg-2) !important;
    color: var(--text-1) !important;
    border: none !important;
    border-radius: 6px !important;
    outline: none !important;
  }

  input:focus,
  textarea:focus,
  select:focus {
    background: var(--bg-3) !important;
  }

  /* ========== SCROLLBAR (minimal) ========== */
  ::-webkit-scrollbar {
    width: 8px !important;
    height: 8px !important;
  }

  ::-webkit-scrollbar-track {
    background: var(--bg-0) !important;
  }

  ::-webkit-scrollbar-thumb {
    background: #333333 !important;
    border-radius: 4px !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #444444 !important;
  }

  /* ========== SELECTION ========== */
  ::selection {
    background: #333333 !important;
    color: #ffffff !important;
  }

  /* ========== CLEAN UP ========== */
  * {
    border-color: transparent !important;
    box-shadow: none !important;
  }

  img {
    opacity: 0.95 !important;
  }
}
